        "services|4:1|4|title": "نرمی سے، مگر مضبوطی سے",
        "services|4:1|4|text": "عمران نے بیلگاوی میں اپنی امی کے لیے آن لائن ایک بجلی کی کیتلی منگوائی، لیکن ڈلیوری ایک ہفتہ دیر سے ہوئی۔ جب امی نے اسے چلایا تو کیتلی سے جلنے کی بو آئی اور وہ بند ہو گئی۔ عمران نے کسٹمر کیئر کو فون کیا، آرڈر نمبر بتایا اور سمجھایا کہ سامان ناقص ہے۔ پہلے ایجنٹ نے صرف ایک واؤچر کی پیشکش کی، اس لیے عمران نے شائستگی سے سپروائزر سے بات کرنے کو کہا۔ وہ پرسکون مگر مضبوط رہا اور بولا، 'معاف کیجیے، واؤچر کافی نہیں ہے، کیتلی وارنٹی میں ہے، اور میرے پاس رسید ہے۔' سپروائزر نے زحمت کے لیے معذرت کی اور دو دن کے اندر نئی کیتلی بھیجنے پر راضی ہو گئیں۔ انہوں نے دیر سے ڈلیوری کے معاوضے کے طور پر اس کے کھاتے میں سو روپے بھی ڈال دیے۔",
