        "services|5:1|4|text": "لکشمی کام کے سلسلے میں شیوموگا سے پونے آ گئی تھی، اس لیے اسے اپنے آدھار کارڈ پر پتا بدلوانا تھا۔ وہ صبح آٹھ بجے آدھار سینٹر پہنچی، لیکن قطار پہلے ہی لمبی تھی۔ ایک گارڈ نے اسے بیالیس نمبر کا ٹوکن اور بھرنے کے لیے ایک درخواست فارم دیا۔ جب اس کی باری آئی تو افسر نے اس کی دستاویزات جانچیں اور پتے کے ثبوت کے طور پر اس کے بجلی کے بل کی فوٹو کاپی مانگی۔ خوش قسمتی سے لکشمی دو کاپیاں لائی تھی، اور ہر صفحے پر پہلے ہی دستخط کر چکی تھی۔ پھر افسر نے تصدیق کے لیے اس کی انگلیوں کے نشان اسکین کیے اور وصولی کی رسید پرنٹ کی۔ اس نے بتایا کہ نیا پتا دس دن کے اندر اپڈیٹ ہو جائے گا، اور لکشمی دوپہر سے پہلے ہی اطمینان سے دفتر سے نکل آئی۔",
