        "workplace|6:1|4|text": "ہر اپریل میں منگلورو میں فریدہ کی کمپنی سالانہ اپریزل میٹنگیں کرتی ہے۔ اپنی میٹنگ سے پہلے اس نے ایمانداری سے اپنا جائزہ لکھا، جس میں اپنی خوبیاں اور ایک واضح کمزوری درج کی: وہ شاذ و نادر ہی مدد مانگتی تھی۔ اس کے مینیجر مسٹر راؤ نے نئے بلنگ سسٹم پر اس کی کارکردگی کی تعریف سے بات شروع کی، جو ٹیم کے لیے ایک بڑا سنگ میل تھا۔ پھر انہوں نے مسئلے جلدی بتانے کے بارے میں اسے کچھ تعمیری مشورے دیے۔ فریدہ نے ان کا شکریہ ادا کیا اور پروجیکٹ مینجمنٹ کی ٹریننگ مانگی۔ مسٹر راؤ ایک سرٹیفکیشن کورس کا خرچ اٹھانے اور اس کے لیے ایک سینئر رہنما ڈھونڈنے پر راضی ہو گئے۔ انہوں نے کہا کہ اس میں ایک دن ٹیم کی قیادت کرنے کی صلاحیت ہے اور وہ تنخواہ میں اچھے اضافے کی حق دار ہے۔ فریدہ آنے والے سال کے لیے ایک واضح منصوبے کے ساتھ میٹنگ سے نکلی۔",
