        "opinions|3:1|4|text": "شریا کوڈاگو کے ایک چھوٹے سے گاؤں میں پلی بڑھی، جہاں اس کا خاندان کافی اگایا کرتا تھا۔ اسے اپنا زیادہ تر بچپن دھندلا سا یاد ہے، لیکن ایک دن آج بھی اس کے ذہن میں بالکل تازہ ہے۔ جب وہ دس سال کی تھی، تیز بارش سے ندی میں سیلاب آ گیا، اور اسکول بس پل پار نہیں کر سکی۔ بچے گھنٹوں سردی میں انتظار کرتے رہے، یہاں تک کہ پونپا نام کا ایک کسان اپنا ٹریکٹر لے کر آیا۔ وہ دو دو تین تین کر کے تیسوں بچوں کو پانی کے پار لے گیا۔ شریا آج بھی وہ چھوٹا سا تولیہ یادگار کے طور پر رکھتی ہے جو اس نے اسے دیا تھا۔ جب بھی تیز بارش ہوتی ہے، اسے اچانک وہ شام یاد آ جاتی ہے۔ اس کے لیے وہ ایک اہم موڑ تھا: اسی دن اس نے طے کیا کہ وہ بھی اپنی زندگی لوگوں کی مدد میں گزارے گی۔",
