        "opinions|4:1|4|title": "پینسٹھ سال کی عمر میں دوسرا موقع",
        "opinions|4:1|4|text": "وینکٹیش پینسٹھ سال کے ہیں اور میسورو میں محل کے پاس اکیلے رہتے ہیں۔ جوانی میں انہیں چنئی میں موسیقی پڑھنے کا موقع ملا تھا، لیکن انہوں نے اس کے بجائے بینک کی ایک محفوظ نوکری چن لی۔ برسوں وہ خود سے کہتے رہے کہ اس سے کوئی فرق نہیں پڑتا، لیکن دل میں ایک خاموش پچھتاوا ہمیشہ رہا۔ 'کاش میں نے ہمت دکھائی ہوتی،' وہ اپنی بیٹی لکشمی سے کہا کرتے تھے۔ پچھلے سال لکشمی نے بڑوں کے لیے شام کی ایک موسیقی کلاس ڈھونڈی اور سالگرہ کے تحفے کے طور پر ان کا نام لکھوا دیا۔ پہلے تو وہ ہنسے اور اسے خام خیالی کہا، لیکن لکشمی نے انہیں ہار نہیں ماننے دی۔ اب وہ ہر صبح وینا کا ریاض کرتے ہیں اور مارچ میں اپنے پہلے چھوٹے کنسرٹ کا بے صبری سے انتظار کر رہے ہیں۔ 'میں ماضی نہیں بدل سکتا،' وہ کہتے ہیں، 'لیکن خوش ہوں کہ آخرکار مجھے دوسرا موقع مل گیا۔'",
