        "opinions|5:1|4|title": "شیوموگا کے دو دوست",
        "opinions|5:1|4|text": "ارون اور پرکاش شیوموگا میں ایک دوسرے کے پڑوس میں پلے بڑھے، اور کرکٹ بیٹ سے لے کر راز تک سب کچھ بانٹتے تھے۔ کالج میں ان کا ایک تلخ جھگڑا ہوا جب پرکاش کو لگا کہ ارون نے اس کا راز دوسروں کو بتا دیا ہے۔ یہ صرف ایک غلط فہمی تھی، لیکن دونوں کی انا اتنی بڑی تھی کہ کوئی بھی پہلے فون نہیں کرنا چاہتا تھا۔ پانچ سال تک دونوں نے بات نہیں کی، اور ان کے دوستوں نے کسی کی طرف داری کرنے سے انکار کر دیا۔ ارون کی امی، جو دونوں لڑکوں سے پیار کرتی تھیں، ہمیشہ امید کرتی رہیں کہ ان کی صلح ہو جائے گی۔ پرکاش کی بہن کی شادی میں آخرکار دونوں آمنے سامنے کھڑے ہوئے۔ پرکاش نے کہا، 'میں ایک بے وقوفانہ وجہ سے دل میں رنجش رکھے بیٹھا تھا، مجھے معاف کر دو۔' ارون نے اسے گلے لگا لیا، اور اس دن کے بعد سے وہ ہر ہفتے رابطے میں رہتے ہیں۔",
