        "opinions|6:1|4|text": "اڈپی کی سنیہا ایک کشمکش میں تھی: اسے احمد آباد کے ایک ڈیزائن کالج میں داخلہ مل گیا تھا، لیکن اس کے امی ابو چاہتے تھے کہ وہ گھر کے قریب پڑھے۔ وہ اپنے خواب اور اپنے خاندان کے بیچ دو راہے پر کھڑی تھی، اس لیے وہ اپنی دادی کے پاس گئی، جن سے وہ ہمیشہ ہر بات پر مشورہ کرتی تھی۔ دادی نے خاموشی سے سنا اور پھر کہا، 'اگر میں تمہاری جگہ ہوتی تو جلدبازی میں فیصلہ نہ کرتی، کچھ دن اچھی طرح سوچ لو۔' انہوں نے رشتے داروں کی باتوں کے بارے میں بھی سنیہا کو ایک نصیحت کی: ان پر آنکھ بند کر کے یقین مت کرنا۔ 'میرا آزمودہ اصول سیدھا ہے،' دادی نے کہا، 'وہ راستہ چنو جس پر ساٹھ سال کی عمر میں پچھتاوا نہ ہو۔' پھر انہوں نے ایک مشورہ دیا: 'کیوں نہ تم اپنے امی ابو کو کالج کی ویب سائٹ اور اپنا پورٹ فولیو دکھاؤ؟' سنیہا نے ان کی بات مانی، اور اس کا کام دیکھنے کے بعد اس کے امی ابو مان گئے۔ آج وہ ہر اتوار دادی کو فون کرتی ہے اور انہیں اپنی کلاسوں کے بارے میں سب کچھ بتاتی ہے۔",
