        "society|2:1|4|text": "ہر شام جے پور میں شرما خاندان ایک ہی کمرے میں بیٹھتا تھا، لیکن کوئی سچ میں بات نہیں کرتا تھا۔ ہر شخص اپنے اسمارٹ فون میں مصروف رہتا، سوشل میڈیا پر اسکرول کرتا یا ویڈیو دیکھتا۔ ایک رات بارہ سال کی ریا نے اپنا اسکرین ٹائم دیکھا اور چھ گھنٹے دیکھ کر دنگ رہ گئی۔ اس نے ایک نیا اصول تجویز کیا: اتوار کو ناشتے سے رات کے کھانے تک کوئی فون نہیں۔ اس کے والد پہلے ہنسے، کیونکہ ان کا فون ہمیشہ دفتر کے نوٹیفکیشنوں سے بھرا رہتا تھا۔ لیکن فون کے بغیر پہلے اتوار کو خاندان نے کیرم کھیلا، مل کر کھانا پکایا اور دادا دادی سے ملنے بھی گئے۔ شام تک کسی کو بھی اپنے فالوور یا تبصرے یاد نہیں آئے۔ اب ہر اتوار شرما خاندان اپنے فون ایک ٹوکری میں رکھ دیتا ہے، اور ریا کہتی ہے کہ یہ ہفتے کا سب سے اچھا دن ہے۔",
