        "society|3:1|3|p4": "فصل کی کٹائی کے بعد پورا گاؤں گانے بجانے اور کھانے کے ساتھ جشن مناتا ہے۔",
        "society|3:1|4|title": "دو گھروں کے بیچ",
        "society|3:1|4|text": "پانچ سال پہلے سنتوش کلبرگی کے پاس اپنا گاؤں چھوڑ کر کام کے لیے بینگلورو آ گیا۔ اب وہ ایک مضافاتی علاقے کے چھوٹے سے فلیٹ میں رہتا ہے اور اپنی آدھی تنخواہ کرائے میں دیتا ہے۔ روز کے آنے جانے میں دو گھنٹے لگتے ہیں، اور ٹریفک جام اس کے صبر کا امتحان لیتے ہیں۔ پھر بھی شہر نے اسے اچھی نوکری اور وہ سہولتیں دی ہیں جو اس کے گاؤں میں کبھی نہیں تھیں۔ پچھلے مہینے وہ فصل کی کٹائی کے لیے گھر گیا اور اس نے محسوس کیا کہ کھیت کتنے پرسکون تھے۔ لیکن اس نے یہ بھی دیکھا کہ اسکول میں صرف ایک استاد تھا اور صحت مرکز ہفتے میں صرف دو بار کھلتا تھا۔ اس نے بچوں کے لیے کمپیوٹر کلاس شروع کرنے کے بارے میں پنچایت سے بات کی۔ سنتوش کا ماننا ہے کہ اگر گاؤوں کو اچھی سہولتیں ملیں تو شہروں کی طرف نقل مکانی کم ہو جائے گی۔",
