        "society|3:1|5|l0": "مہیش، سچ کہوں تو میں کسی ایسی جگہ رہنے کا سوچ بھی نہیں سکتی جہاں میٹرو اور رات گئے کھانے کی ڈلیوری نہ ہو۔",
