        "society|4:1|3|p1": "وہ اپنے خاندان میں ڈگری حاصل کرنے والا پہلا شخص ہے۔",
        "society|4:1|3|p2": "ریاستی وظیفے سے اس کی ہاسٹل فیس اور کتابوں کا خرچ پورا ہو جاتا ہے۔",
