        "society|4:1|3|p4": "کاؤنسلر نے مجھے بتایا کہ عملی ہنر بھی نمبروں جتنے ہی اہم ہیں۔",
        "society|4:1|4|title": "اس کا اپنا راستہ",
        "society|4:1|4|text": "داونگیرے کی نندنی نے پی یو کے امتحانوں میں چورانوے فیصد نمبر حاصل کیے، اور سب کو امید تھی کہ وہ ڈاکٹر بنے گی۔ اس کے امی ابو نے میڈیکل کے داخلہ امتحان کے لیے اسے ایک مہنگے کوچنگ سینٹر میں داخل کرا دیا۔ لیکن نندنی اپنا سارا خالی وقت کالج فیسٹ کے لیے پوسٹر اور چھوٹے ویڈیو بنانے میں گزارتی تھی۔ دباؤ بڑھتا گیا، اور وہ ہر ماک ٹیسٹ سے ڈرنے لگی۔ آخرکار وہ کالج کی کاؤنسلر سے ملی، جنہوں نے غور سے اس کی بات سنی اور ڈیزائن کی ڈگری کے بارے میں جاننے میں اس کی مدد کی۔ دونوں نے مل کر ایک ایسا وظیفہ ڈھونڈا جس سے اس کی زیادہ تر فیس پوری ہو جاتی۔ جب نندنی نے اپنے امی ابو کو اپنا پورٹ فولیو دکھایا، تو اس کے ابو دیر تک خاموش رہے۔ پھر وہ مسکرائے اور بولے، \"اگر یہ تمہارا ہنر ہے، تو یہی تمہارا راستہ ہے۔\"",
        "society|4:1|4|q0": "سب کو نندنی سے کیا بننے کی امید تھی؟",
