        "society|4:1|5|scenario": "آدتیہ نے منگلورو میں ابھی اپنے پی یو کے امتحان ختم کیے ہیں۔ وہ پونے میں کام کرنے والی اپنی بڑی کزن شروتی سے پوچھتا ہے کہ آگے کیا پڑھے۔",
        "society|4:1|5|l0": "تو آدتیہ، نتیجے آ گئے۔ کیا تم نے طے کیا کہ آگے کیا پڑھنا ہے؟",
        "society|4:1|5|l1": "ابھی نہیں۔ سب انجینئرنگ کہتے ہیں، لیکن مجھے یقین نہیں کہ مجھے وہ پسند بھی ہے۔",
