        "society|4:1|5|l3": "سچ کہوں تو معاشیات۔ اور مجھے چیزیں سمجھانا بہت اچھا لگتا ہے، شاید اس لیے کہ میں پڑوسیوں کے بچوں کو ٹیوشن پڑھاتا ہوں۔",
