        "society|4:1|5|l5": "سوچا ہے، لیکن ابا کو فکر ہے کہ اچھی نوکریاں نہیں ملیں گی۔ وہ بار بار مجھے راؤ صاحب کے اس لڑکے سے ملاتے ہیں جس کا آئی آئی ٹی میں داخلہ ہوا۔",
