        "society|5:1|4|title": "کے وائی سی والا فون",
        "society|5:1|4|text": "پچھلے منگل کو میسورو کے ریٹائرڈ استاد وینکٹیش کو ایک آدمی کا فون آیا جس نے کہا کہ وہ ان کے بینک سے ہے۔ فون کرنے والے نے انہیں خبردار کیا کہ اگر انہوں نے فوراً اپنی کے وائی سی تفصیلات اپڈیٹ نہ کیں تو ان کا کھاتا بلاک ہو جائے گا۔ پھر ایک میسج آیا جس میں ایک لنک اور ایک او ٹی پی تھا۔ وینکٹیش او ٹی پی زور سے پڑھنے ہی والے تھے کہ ان کی پوتی آشا نے انہیں روک دیا۔ اس نے سمجھایا کہ بینک کبھی فون پر او ٹی پی نہیں مانگتے اور یہ لنک ایک جعلی ویب سائٹ پر لے جاتا ہے۔ دونوں نے مل کر سائبر کرائم ہیلپ لائن 1930 پر فون کیا اور اس نمبر کی رپورٹ کی۔ بعد میں وہ بینک گئے، جہاں مینیجر نے بتایا کہ یہ ایک عام دھوکا ہے۔ اب وینکٹیش اپنے صبح کی سیر والے گروپ میں سب سے کہتے ہیں کہ فون رکھ دیں اور تصدیق کریں۔",
