        "society|6:1|4|title": "ایک بس اسٹاپ، ایک کالونی",
        "society|6:1|4|text": "جب فریدہ ہبلی کی ایک نئی کالونی میں آئی تو اس نے دیکھا کہ اس کے گھر کے پاس والا بس اسٹاپ کوڑے سے بھرا رہتا ہے۔ شکایت کرنے کے بجائے اس نے ایک نوٹس لگایا اور پڑوسیوں کو سنیچر کی صبح صفائی مہم کے لیے بلایا۔ پہلے ہفتے صرف چھ لوگ آئے، لیکن انہوں نے دو گھنٹے میں پورا علاقہ صاف کر دیا۔ اگلے سنیچر بیس رضاکار آئے، جن میں کئی بزرگ رہائشی بھی تھے جو چائے اور ناشتہ لے کر آئے۔ جلد ہی اس گروپ نے کوڑے دان خریدنے اور بس شیلٹر رنگنے کے لیے ایک چھوٹی سی چندہ مہم شروع کی۔ ایک مقامی دکاندار نے دل کھول کر عطیہ دیا، اور وارڈ کارپوریٹر نے باقاعدہ کوڑا اٹھوانے کا وعدہ کیا۔ آج کالونی کا ایک واٹس ایپ گروپ ہے جہاں پڑوسی خریداری، اسپتال جانے اور بچوں کے ہوم ورک میں ایک دوسرے کی مدد کرتے ہیں۔ فریدہ کہتی ہے کہ صفائی مہم تو بس شروعات تھی، اصل تبدیلی یہ تھی کہ آخرکار لوگ ایک دوسرے کو جاننے لگے۔",
